namespace DynamicAuthBlazor.Web.Providers
{
    public class NotificationStateService
    {
        /// <summary>
        /// Event fired whenever a subpage component requests global background HTTP tracking for a new task.
        /// </summary>
        public event Action<string>? OnJobTrackRequested;

        /// <summary>
        /// Invoked by subpages (e.g., Dashboard.razor) right after receiving an HTTP 202 Accepted response.
        /// </summary>
        /// <param name="jobId">The unique tracking identifier token string generated by the Web API.</param>
        public void RequestJobTracking(string jobId)
        {
            if (string.IsNullOrWhiteSpace(jobId)) return;

            // Triggers the execution handler bound inside MainLayout.razor
            OnJobTrackRequested?.Invoke(jobId);
        }
    }
}
